response.output:
{
  "world_id": "wld_veyra",
  "name": "Veyra, the Unmoored Reach",
  "description": "Veyra is a realm of drifting islands suspended above a luminous sea of cloud. Ancient skybridges once joined its farthest shores, but their joints are failing, and whole communities now vanish beyond the horizon. Cartographers here map not only distance but the changing pull between islands: each accurate chart helps a bridge hold fast. The realm is wondrous and perilous, filled with wind gardens, singing stone, and paths that remember the footsteps of those who built them. A determined mapmaker must restore the bridges before Veyra's scattered peoples lose their last routes to one another.",
  "locations": [
    {
      "id": "loc_larkspire",
      "name": "Larkspire",
      "description": "A terraced island of wind-bent orchards and slate roofs, known for its chartmakers. Its eastern skybridge shivers whenever the island's bell tower rings."
    },
    {
      "id": "loc_morrowarch",
      "name": "Morrow Arch",
      "description": "A vast stone bridge spanning a cloud gulf, its carved keystones shaped like sleeping birds. The bridge's far end now appears in a different place at dawn."
    },
    {
      "id": "loc_tidemark",
      "name": "Tidemark",
      "description": "A low island where cloud tides leave pale salt on the cliffs. Residents preserve old maps in sealed tide-caves, though some charts show islands that no longer exist."
    },
    {
      "id": "loc_bellwether",
      "name": "Bellwether Crown",
      "description": "A ring of narrow pinnacles surrounding a hollow peak. Their natural tones reveal when nearby islands are pulling away from their proper courses."
    },
    {
      "id": "loc_underskein",
      "name": "The Underskein",
      "description": "A hanging forest rooted beneath a drifting island, its silver vines trailing into the clouds. Hidden among the roots are the bridge-makers' old measuring marks."
    },
    {
      "id": "loc_nacrehold",
      "name": "Nacrehold",
      "description": "A crescent-shaped island built around a warm spring. Its residents shelter travelers from separated islands and maintain a small, fragile crossing toward Larkspire."
    }
  ],
  "factions": [
    {
      "id": "fac_atlas_covenant",
      "name": "The Atlas Covenant",
      "description": "A fellowship of mapmakers who believe every island must be charted in relation to its neighbors. They seek to repair the skybridges, but guard their oldest measurements closely.",
      "location_ids": [
        "loc_larkspire",
        "loc_tidemark"
      ]
    },
    {
      "id": "fac_keystone_wardens",
      "name": "Keystone Wardens",
      "description": "Bridge keepers sworn to maintain the ancient spans. They favor immediate repairs, even when the work may fasten an island to a dangerous course.",
      "location_ids": [
        "loc_morrowarch",
        "loc_bellwether"
      ]
    },
    {
      "id": "fac_roving_hearths",
      "name": "Roving Hearths",
      "description": "A loose alliance of families whose homes travel with the islands. They want safe passage restored, yet fear that fixed bridges will erase the freedom that kept them alive.",
      "location_ids": [
        "loc_underskein",
        "loc_nacrehold"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_chart_tether",
      "statement": "An island holds its course only while at least one living chart records its changing relation to a neighboring island.",
      "category": "metaphysics"
    },
    {
      "id": "rul_bridge_memory",
      "statement": "A skybridge remembers the first route its builders walked across it, and repairs made along that route endure longest.",
      "category": "metaphysics"
    },
    {
      "id": "rul_cloud_tide",
      "statement": "Cloud tides rise and fall in slow cycles, carrying loose objects and unmoored islands toward the realm's outer reaches.",
      "category": "physics"
    },
    {
      "id": "rul_bell_measure",
      "statement": "The tones of Bellwether Crown can be heard only by people standing on stone; their intervals reveal shifts in the islands' pull.",
      "category": "physics"
    },
    {
      "id": "rul_chart_custody",
      "statement": "No single household may keep the only known chart of a route; a copy must be entrusted to another island.",
      "category": "social"
    }
  ],
  "history": [
    {
      "id": "evt_first_measure",
      "name": "The First Measure",
      "description": "The earliest bridge-makers discovered that islands drifted less when their distances were drawn and shared. They laid the first spans along the routes recorded in those charts.",
      "era": "Age of Joining",
      "location_ids": [
        "loc_morrowarch",
        "loc_larkspire"
      ]
    },
    {
      "id": "evt_silent_crossing",
      "name": "The Silent Crossing",
      "description": "A bridge crew altered a span to reach a richer island without consulting its keepers. The island pulled away, and the bridge's stones went quiet; its failure began the tradition of shared chart custody.",
      "era": "Age of Joining",
      "location_ids": [
        "loc_tidemark",
        "loc_bellwether"
      ]
    },
    {
      "id": "evt_unmooring",
      "name": "The Unmooring",
      "description": "A series of cloud tides swept through the realm, exposing old measuring marks beneath a drifting island. The marks suggest the first builders mapped not just routes between islands, but the shape of a hidden pattern connecting them all.",
      "era": "The Recent Drift",
      "location_ids": [
        "loc_underskein",
        "loc_nacrehold"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_route_or_root",
      "name": "Route or Root",
      "description": "The Wardens want to fasten Morrow Arch to its old route before the next cloud tide, while the Covenant argues that its chart is incomplete. The Roving Hearths warn that the proposed course would pull their traveling homes into the bridge's path.",
      "faction_ids": [
        "fac_atlas_covenant",
        "fac_keystone_wardens",
        "fac_roving_hearths"
      ]
    },
    {
      "id": "cnf_hidden_pattern",
      "name": "The Hidden Pattern",
      "description": "The Covenant suspects the old measuring marks point to a chart capable of stabilizing several islands at once. The Wardens want the chart used immediately; the Roving Hearths fear it could bind every island to one unchanging course.",
      "faction_ids": [
        "fac_atlas_covenant",
        "fac_keystone_wardens",
        "fac_roving_hearths"
      ]
    }
  ]
}

