response.output:
{
  "world_id": "wld_vesper_lattice",
  "name": "The Vesper Lattice",
  "description": "Humanity lives across a habitat swarm circling Vesper, a star entering its final, unstable centuries. The habitats are not arranged as a tidy shell: they drift in carefully maintained orbital lanes, each balancing its neighbors' shade, power, and access to the star. Couriers cross those lanes with physical records and sealed components, carrying news between communities that rarely agree on what the swarm should become. When one courier finds a message apparently left by the original builders, its contents suggest the swarm was designed for a purpose its descendants have forgotten. The message is incomplete, and every attempt to read it risks changing the orbital pattern that keeps millions alive. A thoughtful science-fiction setting about inheritance, collective responsibility, and the cost of learning who made the home you depend on.",
  "locations": [
    {
      "id": "loc_vesper_crown",
      "name": "Vesper Crown",
      "description": "A belt of power-collecting mirrors and maintenance platforms closest to the star. Its crews live by strict exposure schedules, and its shifting shadows determine how much energy reaches the outer habitats."
    },
    {
      "id": "loc_loom",
      "name": "The Loom",
      "description": "A dense knot of rotating habitats, docks, and transfer rails where most courier routes intersect. Its traffic controllers treat orbital positions as public infrastructure, not private property."
    },
    {
      "id": "loc_tideglass",
      "name": "Tideglass",
      "description": "A water-rich agricultural habitat whose long internal lakes serve as both food reserves and radiation shielding. Residents keep their oldest records etched into flood gates and canal walls."
    },
    {
      "id": "loc_umbra_yard",
      "name": "Umbra Yard",
      "description": "A repair settlement built in the shadow of a defunct collector. Its salvage crews recover obsolete machinery, including components whose original functions have no surviving documentation."
    },
    {
      "id": "loc_keystone",
      "name": "Keystone Vault",
      "description": "A sealed, uncrewed structure on a stable outer orbit, identified in old navigation tables but absent from every living registry. A new signal from within carries the same timing pattern as the swarm's oldest control beacons."
    }
  ],
  "factions": [
    {
      "id": "fac_lane_compact",
      "name": "Lane Compact",
      "description": "A coalition of traffic stewards who preserve the swarm's inherited orbital schedule. They fear that probing the builders' message could trigger a chain of corrections no community can safely reverse.",
      "location_ids": [
        "loc_loom",
        "loc_vesper_crown"
      ]
    },
    {
      "id": "fac_open_record",
      "name": "Open Record",
      "description": "Archivists, couriers, and technicians who believe the builders' message belongs to everyone. They want to decode it in public, even if its instructions challenge current law.",
      "location_ids": [
        "loc_tideglass",
        "loc_umbra_yard"
      ]
    },
    {
      "id": "fac_keystone_watch",
      "name": "Keystone Watch",
      "description": "A small, unofficial crew maintaining a listening post near the unexplained vault. They have detected replies in the beacon pattern but have kept the discovery secret to avoid a rush toward the structure.",
      "location_ids": [
        "loc_keystone",
        "loc_umbra_yard"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_orbit_exchange",
      "statement": "Every habitat's orbit is coupled to its neighbors through timed exchanges of mass, momentum, and navigational data; an unscheduled shift can endanger multiple communities.",
      "category": "physics"
    },
    {
      "id": "rul_solar_decay",
      "statement": "Vesper's output is declining unevenly, so no habitat can rely on a fixed power allotment from one season to the next.",
      "category": "physics"
    },
    {
      "id": "rul_closed_material",
      "statement": "No settlement can import new matter from beyond the swarm at a meaningful scale; repairs and growth depend on recovery, reuse, and careful accounting.",
      "category": "technology"
    },
    {
      "id": "rul_shared_lanes",
      "statement": "A habitat's assigned lane is held in trust for all residents of the swarm and cannot be permanently claimed by a single council or household.",
      "category": "social"
    },
    {
      "id": "rul_signal_cost",
      "statement": "The old control beacons answer only when nearby transmitters match their timing precisely, and each exchange briefly disrupts ordinary navigation signals.",
      "category": "technology"
    }
  ],
  "history": [
    {
      "id": "evt_first_lanes",
      "name": "The First Lanes",
      "description": "The earliest surviving records describe the placement of habitats and collectors as a coordinated construction, though they name no builders and give no account of the plan's original goal.",
      "era": "Founding era",
      "location_ids": [
        "loc_vesper_crown",
        "loc_loom"
      ]
    },
    {
      "id": "evt_registry_split",
      "name": "The Registry Split",
      "description": "After a failed power transfer, communities disputed which records were authoritative. The resulting split scattered technical archives across habitats and made shared maintenance a matter of negotiation.",
      "era": "Era of divided ledgers",
      "location_ids": [
        "loc_tideglass",
        "loc_loom"
      ]
    },
    {
      "id": "evt_collector_dark",
      "name": "The Collector Went Dark",
      "description": "A collector ceased responding to its control beacons. Salvage crews founded Umbra Yard nearby, and the loss forced the swarm to revise its power schedule.",
      "era": "Three generations ago",
      "location_ids": [
        "loc_vesper_crown",
        "loc_umbra_yard"
      ]
    },
    {
      "id": "evt_vault_reply",
      "name": "A Reply in the Noise",
      "description": "Keystone Watch detected a repeated pattern beneath routine beacon traffic. Its timing matched an old construction mark, but the crew concealed the result while verifying that the signal was not an orbital fault.",
      "era": "Current era",
      "location_ids": [
        "loc_keystone",
        "loc_umbra_yard"
      ]
    },
    {
      "id": "evt_courier_message",
      "name": "The Courier's Find",
      "description": "A courier carrying recovered components found a message nested in a device from the defunct collector. Its first readable sequence points toward the sealed vault and warns that the swarm's present arrangement is only one phase of a larger design.",
      "era": "Current era",
      "location_ids": [
        "loc_umbra_yard",
        "loc_keystone"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_decode_or_stabilize",
      "name": "Decode or Stabilize",
      "description": "The signal from the vault could reveal how to adapt the swarm to Vesper's decline, but decoding it may interrupt navigation at a dangerous moment. The Lane Compact demands a safe schedule first; Open Record argues that delay gives a few stewards control over a discovery that affects everyone.",
      "faction_ids": [
        "fac_lane_compact",
        "fac_open_record"
      ]
    },
    {
      "id": "cnf_secret_reply",
      "name": "The Unshared Reply",
      "description": "Keystone Watch has evidence that the vault is responding, while Open Record suspects the crew is withholding a public inheritance. A courier's discovery could expose the secret and force the Watch to choose between preserving its cautious investigation and trusting the wider swarm.",
      "faction_ids": [
        "fac_keystone_watch",
        "fac_open_record"
      ]
    },
    {
      "id": "cnf_shadow_budget",
      "name": "The Shadow Budget",
      "description": "As Vesper dims, the collector crews must decide which habitats receive scarce light and power. Any revised schedule shifts costs onto particular communities, threatening the shared-lane compact and giving every faction reason to contest the builders' old plan.",
      "faction_ids": [
        "fac_lane_compact",
        "fac_keystone_watch",
        "fac_open_record"
      ]
    }
  ]
}

