response.output:
{
  "world_id": "wld_velvet_rain",
  "name": "Velvet Rain",
  "description": "A rain-bound metropolis of black glass, elevated railways, and shuttered waterfronts, where a private investigator follows a blackmailer through a maze of suspect alibis. In this noir city, rain leaves a brief silver film on every window; for a few minutes, it reflects the last face seen inside, making storm-lit streets an unreliable witness and a prized source of evidence. The powerful trade in secrets, the desperate trade in time, and almost everyone has a reason to be somewhere else.",
  "locations": [
    {
      "id": "loc_morrow_quay",
      "name": "Morrow Quay",
      "description": "A narrow harbor district of tide stairs and rain-black warehouses. Its window reflections can preserve a fleeting image after a room has emptied, though the harbor fog often blurs the details."
    },
    {
      "id": "loc_lantern_exchange",
      "name": "The Lantern Exchange",
      "description": "A former tram depot converted into a night market for favors, sealed letters, and carefully rehearsed alibis. Vendors rent brass booths by the hour and never ask who is waiting outside."
    },
    {
      "id": "loc_mercy_steps",
      "name": "Mercy Steps",
      "description": "A steep hillside neighborhood where stairways connect boarding houses, a courthouse annex, and a clock tower that runs seven minutes slow. Residents use the mismatch to explain their late arrivals."
    }
  ],
  "factions": [
    {
      "id": "fac_window_clerks",
      "name": "The Window Clerks",
      "description": "A discreet circle of night cleaners who catalogue faces preserved in rain-fogged glass. They sell verified sightings, but each clerk keeps one image hidden for personal leverage.",
      "location_ids": [
        "loc_morrow_quay",
        "loc_mercy_steps"
      ]
    },
    {
      "id": "fac_lantern_union",
      "name": "Lantern Union",
      "description": "The market's booth keepers, message runners, and favor brokers. They protect the Exchange's secrecy while quietly deciding which rumors deserve to reach the streets.",
      "location_ids": [
        "loc_lantern_exchange"
      ]
    },
    {
      "id": "fac_civic_timekeepers",
      "name": "Civic Timekeepers",
      "description": "Courthouse clerks and clock technicians who maintain the city's official schedules. Their records can confirm an alibi or make a witness appear to have arrived before an event occurred.",
      "location_ids": [
        "loc_mercy_steps",
        "loc_lantern_exchange"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_rain_reflection",
      "statement": "After a hard shower, a glazed window holds the last indoor face it reflected for roughly three minutes, then clears without a trace.",
      "category": "other"
    },
    {
      "id": "rul_clock_discrepancy",
      "statement": "No public clock in the city agrees with every other public clock; official records rely on the courthouse master dial.",
      "category": "technology"
    },
    {
      "id": "rul_alibi_custom",
      "statement": "A credible alibi requires two independent witnesses or one surviving rain-glass image, and neither source is presumed honest.",
      "category": "social"
    },
    {
      "id": "rul_night_routes",
      "statement": "The harbor tram stops during the deepest hours of the night, leaving the stairways and footbridges as the only public routes between the lower quay and the hill.",
      "category": "technology"
    }
  ],
  "history": [
    {
      "id": "evt_silver_shower",
      "name": "The Silver Shower",
      "description": "A storm once revealed a councilman's secret meeting on a courthouse window. The image vanished before it could be entered into evidence, but the rumor changed how the city treats every rain-streaked pane.",
      "era": "The year the old council fell",
      "location_ids": [
        "loc_mercy_steps"
      ]
    },
    {
      "id": "evt_market_charter",
      "name": "The Lantern Charter",
      "description": "After a series of disappearances along the waterfront, booth keepers agreed to shelter messengers and keep a private ledger of who had purchased which favor. No one has seen the complete ledger.",
      "era": "The first winter after the Silver Shower",
      "location_ids": [
        "loc_lantern_exchange",
        "loc_morrow_quay"
      ]
    },
    {
      "id": "evt_seven_minute_flood",
      "name": "The Seven-Minute Flood",
      "description": "A tidal surge stopped the hill clocks while the courthouse master dial kept running. Conflicting arrival times saved several suspects from inquiry and established the city's enduring clock discrepancy.",
      "era": "The year the harbor wall broke",
      "location_ids": [
        "loc_morrow_quay",
        "loc_mercy_steps"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_hidden_ledger",
      "name": "The Ledger's Missing Page",
      "description": "Someone is blackmailing prominent residents with details from the Lantern Union's private records. The Union suspects a clerk has copied its ledger, while the Window Clerks believe the blackmailer is using rain-glass sightings to fabricate impossible alibis.",
      "faction_ids": [
        "fac_lantern_union",
        "fac_window_clerks"
      ]
    },
    {
      "id": "cnf_master_dial",
      "name": "The Master Dial Dispute",
      "description": "The Civic Timekeepers plan to correct the courthouse dial, which would invalidate years of convenient arrival records. The Union wants the old discrepancy preserved; several people under investigation need it erased.",
      "faction_ids": [
        "fac_civic_timekeepers",
        "fac_lantern_union"
      ]
    },
    {
      "id": "cnf_last_face",
      "name": "The Face in the Glass",
      "description": "A Window Clerk has concealed a reflection that may identify the blackmailer, but releasing it would expose an informant whose testimony supports a fragile alibi.",
      "faction_ids": [
        "fac_window_clerks",
        "fac_civic_timekeepers"
      ]
    }
  ]
}

