        "fac_civic_timekeepers"
      ]
    }
  ]
}

{
  "world_id": "wld_velvet_rain",
  "name": "Velvet Rain",
  "description": "A rain-bound metropolis of black glass, elevated railways, and shuttered waterfronts, where a private investigator follows a blackmailer through a maze of suspect alibis. In this noir city, rain leaves a brief silver film on every window; for a few minutes, it reflects the last face seen inside, making storm-lit streets an unreliable witness and a prized source of evidence. The powerful trade in secrets, the desperate trade in time, and almost everyone has a reason to be somewhere else.",
  "locations": [
    {
      "id": "loc_morrow_quay",
      "name": "Morrow Quay",
      "description": "A narrow harbor district of tide stairs and rain-black warehouses. Its window reflections can preserve a fleeting image after a room has emptied, though the harbor fog often blurs the details."
    },
    {
      "id": "loc_lantern_exchange",
      "name": "The Lantern Exchange",
      "description": "A former tram depot converted into a night market for favors, sealed letters, and carefully rehearsed alibis. Vendors rent brass booths by the hour and never ask who is waiting outside."
    },
    {
      "id": "loc_mercy_steps",
      "name": "Mercy Steps",
      "description": "A steep hillside neighborhood where stairways connect boarding houses, a courthouse annex, and a clock tower that runs seven minutes slow. Residents use the mismatch to explain their late arrivals."
    }
  ],
  "factions": [
    {
      "id": "fac_window_clerks",
      "name": "The Window Clerks",
      "description": "A discreet circle of night cleaners who catalogue faces preserved in rain-fogged glass. They sell verified sightings, but each clerk keeps one image hidden for personal leverage.",
      "location_ids": [
        "loc_morrow_quay",
        "loc_mercy_steps"
      ]
    },
    {
      "id": "fac_lantern_union",
      "name": "Lantern Union",
      "description": "The market's booth keepers, message runners, and favor brokers. They protect the Exchange's secrecy while quietly deciding which rumors deserve to reach the streets.",
      "location_ids": [
        "loc_lantern_exchange"
      ]
    },
    {
      "id": "fac_civic_timekeepers",
      "name": "Civic Timekeepers",
      "description": "Courthouse clerks and clock technicians who maintain the city's official schedules. Their records can confirm an alibi or make a witness appear to have arrived before an event occurred.",
      "location_ids": [
        "loc_mercy_steps",
        "loc_lantern_exchange"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_rain_reflection",
      "statement": "After a hard shower, a glazed window holds the last indoor face it reflected for roughly three minutes, then clears without a trace.",
      "category": "other"
    },
    {
      "id": "rul_clock_discrepancy",
      "statement": "No public clock in the city agrees with every other public clock; official records rely on the courthouse master dial.",
      "category": "technology"
    },
    {
      "id": "rul_alibi_custom",
      "statement": "A credible alibi requires two independent witnesses or one surviving rain-glass image, and neither source is presumed honest.",
      "category": "social"
    },
    {
      "id": "rul_night_routes",
      "statement": "The harbor tram stops during the deepest hours of the night, leaving the stairways and footbridges as the only public routes between the lower quay and the hill.",
      "category": "technology"
    }
  ],
  "history": [
    {
      "id": "evt_silver_shower",
      "name": "The Silver Shower",
      "description": "A storm once revealed a councilman's secret meeting on a courthouse window. The image vanished before it could be entered into evidence, but the rumor changed how the city treats every rain-streaked pane.",
      "era": "The year the old council fell",
      "location_ids": [
        "loc_mercy_steps"
      ]
    },
    {
      "id": "evt_market_charter",
      "name": "The Lantern Charter",
      "description": "After a series of disappearances along the waterfront, booth keepers agreed to shelter messengers and keep a private ledger of who had purchased which favor. No one has seen the complete ledger.",
      "era": "The first winter after the Silver Shower",
      "location_ids": [
        "loc_lantern_exchange",
        "loc_morrow_quay"
      ]
    },
    {
      "id": "evt_seven_minute_flood",
      "name": "The Seven-Minute Flood",
      "description": "A tidal surge stopped the hill clocks while the courthouse master dial kept running. Conflicting arrival times saved several suspects from inquiry and established the city's enduring clock discrepancy.",
      "era": "The year the harbor wall broke",
      "location_ids": [
        "loc_morrow_quay",
        "loc_mercy_steps"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_hidden_ledger",
      "name": "The Ledger's Missing Page",
      "description": "Someone is blackmailing prominent residents with details from the Lantern Union's private records. The Union suspects a clerk has copied its ledger, while the Window Clerks believe the blackmailer is using rain-glass sightings to fabricate impossible alibis.",
      "faction_ids": [
        "fac_lantern_union",
        "fac_window_clerks"
      ]
    },
    {
      "id": "cnf_master_dial",
      "name": "The Master Dial Dispute",
      "description": "The Civic Timekeepers plan to correct the courthouse dial, which would invalidate years of convenient arrival records. The Union wants the old discrepancy preserved; several people under investigation need it erased.",
      "faction_ids": [
        "fac_civic_timekeepers",
        "fac_lantern_union"
      ]
    },
    {
      "id": "cnf_last_face",
      "name": "The Face in the Glass",
      "description": "A Window Clerk has concealed a reflection that may identify the blackmailer, but releasing it would expose an informant whose testimony supports a fragile alibi.",
      "faction_ids": [
        "fac_window_clerks",
        "fac_civic_timekeepers"
      ]
    }
  ]
}

response.output:
{
  "world_id": "wld_vesper_sound",
  "name": "The Vesper Sound",
  "description": "In the Vesper Sound, a wall of fog seals the sea around the luxury liner Aurelia, missing for forty years and newly found by a salvage crew. Its brass fittings still gleam, its dining room is set for a final course, and its empty corridors carry the muffled rhythm of a dance. The ship is not empty: its lost passengers linger as if the voyage has barely begun. The crew came to strip the liner of its valuables, but the vessel keeps rearranging its passages, and each recovered object seems to make the dead more aware of their visitors. Oppressive and intimate, this world turns a salvage operation into a contest over who gets to leave with their name, their memories, and their life intact.",
  "locations": [
    {
      "id": "loc_aurelia_deck",
      "name": "Aurelia's Grand Promenade",
      "description": "A sweeping interior deck of dark mahogany, tarnished mirrors, and sealed portholes. The fog presses against the glass from outside, though the liner rests in deep water. A dance band plays somewhere beyond the ballroom doors, always finishing the same unfinished measure."
    },
    {
      "id": "loc_aurelia_engine",
      "name": "The Flooded Engine Chapel",
      "description": "Below the waterline, the engine room has become a still, waist-deep chamber. The engines are cold, yet their gauges twitch when anyone speaks a passenger's name. A narrow maintenance ladder leads upward, but never to the deck from which a diver descended."
    }
  ],
  "factions": [
    {
      "id": "fac_salvage_crew",
      "name": "Morrow Salvage",
      "description": "A small, debt-ridden crew hired to recover the Aurelia's valuables. Their captain insists on a strict inventory, fearing that anything unrecorded will be impossible to prove they ever found. Members disagree over whether the ship's human remains count as cargo.",
      "location_ids": [
        "loc_aurelia_deck",
        "loc_aurelia_engine"
      ]
    },
    {
      "id": "fac_unlisted",
      "name": "The Unlisted",
      "description": "The liner's dead passengers, whose names have vanished from the ship's manifests. They appear in reflections and at the edges of the fog, dressed for an evening that never ended. They can speak clearly only when someone aboard gives them a name to answer to.",
      "location_ids": [
        "loc_aurelia_deck",
        "loc_aurelia_engine"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_fog_boundary",
      "statement": "The fog surrounds the Aurelia without drifting away, and no signal sent from within it reaches the outside world.",
      "category": "metaphysics"
    },
    {
      "id": "rul_name_echo",
      "statement": "When a living person speaks the name of someone lost aboard, the ship answers with that person's voice from somewhere nearby.",
      "category": "metaphysics"
    },
    {
      "id": "rul_passage_shift",
      "statement": "The Aurelia's interior passages change only when no living observer is watching them.",
      "category": "other"
    },
    {
      "id": "rul_manifest_cost",
      "statement": "Writing a missing passenger's name into the ship's manifest makes that passenger visible, but erases one memory of the writer's own.",
      "category": "metaphysics"
    }
  ],
  "history": [
    {
      "id": "evt_last_supper",
      "name": "The Last Supper",
      "description": "On the night the Aurelia vanished, its passengers gathered for a formal dinner. The ship's manifest was found later in a lifeboat, every passenger name scraped away except for one blank line.",
      "era": "Forty years ago",
      "location_ids": [
        "loc_aurelia_deck"
      ]
    },
    {
      "id": "evt_first_ping",
      "name": "The Returning Signal",
      "description": "A distress signal bearing the Aurelia's call sign began repeating across a dead frequency. Its coordinates shifted with each transmission until Morrow Salvage traced it to the fog.",
      "era": "Present day",
      "location_ids": [
        "loc_aurelia_deck",
        "loc_aurelia_engine"
      ]
    },
    {
      "id": "evt_engine_stop",
      "name": "The Unwinding Engine",
      "description": "The first divers to reach the engine room found its gauges counting backward. When one read aloud a passenger's name, every dial stopped at once, and a voice answered from the flooded dark.",
      "era": "Present day",
      "location_ids": [
        "loc_aurelia_engine"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_manifest_claim",
      "name": "Who Owns the Names",
      "description": "Morrow Salvage wants the manifest as proof of the wreck's identity and as a key to a valuable claim. The Unlisted need their names spoken and recorded to become whole, but each entry costs the writer a personal memory. The crew must decide whether to complete the record, destroy it, or bargain with the dead before the ship closes around them.",
      "faction_ids": [
        "fac_salvage_crew",
        "fac_unlisted"
      ]
    }
  ]
}

