response.output:
{
  "world_id": "wld_verdant_crown",
  "name": "The Green Meridian",
  "description": "Beyond the fever coast lies a jungle that swallows trails, camps, and the people who trust them. At its heart stands a lost city of black stone, where the reluctant guide Mara Venn must lead rival treasure hunters through a wilderness that seems to remember every trespass. This is a pulp world of perilous crossings, old maps, quick bargains, and ruins whose strangest law is simple: the jungle grows fastest along the paths people name aloud.",
  "locations": [
    {
      "id": "loc_fever_coast",
      "name": "Fever Coast",
      "description": "A humid strip of mangroves and yellow sand where expedition boats unload beneath clouds of biting insects. Local pilots know the tides but rarely venture inland."
    },
    {
      "id": "loc_bellwater",
      "name": "Bellwater Camp",
      "description": "A ramshackle outpost built around a spring that rings softly at dawn. Mara Venn's maps begin here, though the spring's source has never been found."
    },
    {
      "id": "loc_greenmaze",
      "name": "The Green Maze",
      "description": "A tangled jungle basin of strangler figs, flooded gullies, and vines that knot themselves across freshly spoken routes. Old trail markers surface in places they were not planted."
    },
    {
      "id": "loc_drowned_steps",
      "name": "Drowned Steps",
      "description": "A broad stone staircase descends into a clear sinkhole. Carved footprints point both upward and down, and the water level rises whenever a bell rings in the distance."
    },
    {
      "id": "loc_crown_gate",
      "name": "Crown Gate",
      "description": "A pair of leaning towers marks the outer wall of the lost city. Their stone faces bear hundreds of erased names, and a narrow breach opens only at midday."
    },
    {
      "id": "loc_lost_city",
      "name": "The City of Roots",
      "description": "A vast city of black terraces and roofless halls, bound together by living roots. At its center, a stone compass turns toward whoever has most recently tried to leave."
    },
    {
      "id": "loc_sunwell",
      "name": "Sunwell Court",
      "description": "A sunken plaza inside the city, where a golden basin catches a beam of light even beneath the canopy. Legends claim the basin can reveal a path, but never the same one twice."
    }
  ],
  "factions": [
    {
      "id": "fac_riverwardens",
      "name": "Riverwardens",
      "description": "Local boat families who keep the coast and spring routes open. They will guide outsiders only if the visitors leave the jungle's carved stones untouched.",
      "location_ids": ["loc_fever_coast", "loc_bellwater"]
    },
    {
      "id": "fac_meridian_society",
      "name": "Meridian Society",
      "description": "A polished club of collectors and backers seeking the city's golden basin. Their expedition has money, maps, and little patience for anyone who says the jungle has rules.",
      "location_ids": ["loc_bellwater", "loc_crown_gate", "loc_lost_city"]
    },
    {
      "id": "fac_rootkeepers",
      "name": "Rootkeepers",
      "description": "A secretive circle of city descendants who maintain the old terraces and conceal the Sunwell Court. They believe every spoken route feeds the jungle's appetite.",
      "location_ids": ["loc_greenmaze", "loc_drowned_steps", "loc_sunwell"]
    }
  ],
  "rules": [
    {
      "id": "rul_named_paths",
      "statement": "A route spoken aloud in the jungle draws new growth across itself before the next dawn.",
      "category": "metaphysics"
    },
    {
      "id": "rul_bellwater_tide",
      "statement": "The spring at Bellwater rings at dawn, and its sound carries farther inland than any other sound.",
      "category": "physics"
    },
    {
      "id": "rul_city_compass",
      "statement": "The compass at the city's center points toward the person most determined to escape.",
      "category": "metaphysics"
    },
    {
      "id": "rul_no_stone_names",
      "statement": "The Riverwardens forbid removing or altering carved stones along inland waterways.",
      "category": "social"
    },
    {
      "id": "rul_midday_breach",
      "statement": "The breach in Crown Gate opens only while the sun stands directly above the towers.",
      "category": "other"
    }
  ],
  "history": [
    {
      "id": "evt_city_abandoned",
      "name": "The Silent Departure",
      "description": "The city's inhabitants left no records of a battle or disaster; only erased names and abandoned tools remained. The jungle closed the main roads soon afterward.",
      "era": "The Last City Era",
      "location_ids": ["loc_crown_gate", "loc_lost_city"]
    },
    {
      "id": "evt_spring_found",
      "name": "The First Bell",
      "description": "Riverwardens discovered the inland spring after hearing its dawn ring from the coast. They marked the safe approach with stones and swore never to speak the full route.",
      "era": "The Early Riverwardens",
      "location_ids": ["loc_fever_coast", "loc_bellwater"]
    },
    {
      "id": "evt_compass_taken",
      "name": "The Collector's Attempt",
      "description": "A previous Meridian Society party reached the central compass and tried to carry it away. The jungle swallowed their camp, while the compass reappeared facing the coast.",
      "era": "A Generation Ago",
      "location_ids": ["loc_greenmaze", "loc_lost_city"]
    },
    {
      "id": "evt_sunwell_hidden",
      "name": "The Basin Veiled",
      "description": "The Rootkeepers concealed the Sunwell Court after an intruder used its light to guide a raiding party into the city.",
      "era": "The Rootkeepers' Founding",
      "location_ids": ["loc_sunwell", "loc_drowned_steps"]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_basin_race",
      "name": "The Basin Race",
      "description": "The Meridian Society wants the Sunwell basin as proof of its claim to the city; the Rootkeepers want it hidden. The Riverwardens are caught between protecting their routes and keeping the expedition from turning the coast into a staging ground.",
      "faction_ids": ["fac_meridian_society", "fac_rootkeepers", "fac_riverwardens"]
    },
    {
      "id": "cnf_unspoken_route",
      "name": "The Unspoken Route",
