      "description": "A smoke-darkened council chamber built around nine bronze lamps, where senatorial votes are cast in public and the water clock's emptied bowls are kept in a locked archive."
    },
    {
      "id": "loc_salt_quay",
      "name": "Salt Quay",
      "description": "The city's crowded harbor of grain barges, customs sheds, and salt-stained warehouses. Dockworkers hear news before the council does, and a delayed shipment can turn rumor into hunger."
    },
    {
      "id": "loc_red_forum",
      "name": "The Red Forum",
      "description": "A broad plaza paved in rust-colored stone, ringed by bakeries and public steps. Varro's speeches draw thousands here, where the crowd can see the senate hall on the hill."
    },
    {
      "id": "loc_old_cistern",
      "name": "The Old Cistern",
      "description": "A vaulted reservoir beneath the oldest district, its water channels still feeding the public clocks. A sealed maintenance passage links it to forgotten records below the Hall of Nine Lamps."
    }
  ],
  "factions": [
    {
      "id": "fac_house_lamps",
      "name": "The House of Lamps",
      "description": "The senatorial bloc that prizes civic order and inherited procedure. Its members fear Varro's crowds, but many quietly resent Cassian for the levy scandal.",
      "location_ids": [
        "loc_senate_hall"
      ]
    },
    {
      "id": "fac_open_hand",
      "name": "The Open Hand",
      "description": "A populist coalition of market sellers, indebted artisans, and demobilized guards rallied by Lucan Varro. It wants debt remissions and a public assembly with power to overrule the senate.",
      "location_ids": [
        "loc_red_forum",
        "loc_salt_quay"
      ]
    },
    {
      "id": "fac_cistern_keepers",
      "name": "The Cistern Keepers",
      "description": "A small guild of water stewards and clock tenders who maintain Vesperis's reservoirs and official speech timers. Their ledgers preserve discrepancies that powerful families would rather leave forgotten.",
      "location_ids": [
        "loc_old_cistern",
        "loc_senate_hall"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_public_clock",
      "statement": "Every formal civic speech is timed by a water clock whose emptied bowl must be entered into the public record.",
      "category": "social"
    },
    {
      "id": "rul_grain_levy",
      "statement": "The senate may levy grain for the city's reserve, but release of that reserve requires a recorded vote and a countersignature from the harbor magistrate.",
      "category": "social"
    },
    {
      "id": "rul_civic_water",
      "statement": "The cistern channels are maintained by hand and gravity; no device in the city can move water without a visible source of force.",
      "category": "physics"
    },
    {
      "id": "rul_craft_limit",
      "statement": "Tools and weapons rely on muscle, leverage, fire, and skilled metalwork; no craft can produce a sudden distant blast.",
      "category": "technology"
    }
  ],
  "history": [
    {
      "id": "evt_nine_lamps",
      "name": "The Compact of Nine Lamps",
      "description": "After rival harbor houses nearly set the city against itself, nine families agreed to share power through a council whose votes and speeches would be recorded beneath nine ever-burning lamps.",
      "era": "Founding era",
      "location_ids": [
        "loc_senate_hall"
      ]
    },
    {
      "id": "evt_silt_flood",
      "name": "The Silt Flood",
      "description": "A breach in the lower channels inundated the old district. The Cistern Keepers restored the water supply, then secured permanent custody of the clockworks and their ledgers.",
      "era": "Three generations ago",
      "location_ids": [
        "loc_old_cistern"
      ]
    },
    {
      "id": "evt_failed_levy",
      "name": "The Winter Levy",
      "description": "Cassian Meret oversaw a grain levy meant to fill the city reserve, but much of the shipment vanished before it reached the warehouses. The senate censured him; the market wards blamed the council.",
      "era": "Last winter",
      "location_ids": [
        "loc_salt_quay",
        "loc_senate_hall"
      ]
    },
    {
      "id": "evt_varro_rise",
      "name": "The Bowl That Ran Dry",
      "description": "Varro spoke in the Red Forum until the water clock emptied, then demanded the bowl be entered as proof that the people had waited long enough. The keepers recorded the time, and his following swelled.",
      "era": "Present season",
      "location_ids": [
        "loc_red_forum"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_authority",
      "name": "The Council and the Crowd",
      "description": "The House of Lamps seeks to preserve senatorial rule, while the Open Hand demands that the assembly control grain and debt policy. Cassian must decide whether to expose the council's own failures or give Varro a pretext to seize power.",
      "faction_ids": [
        "fac_house_lamps",
        "fac_open_hand"
      ]
    },
    {
      "id": "cnf_missing_grain",
      "name": "The Vanished Reserve",
      "description": "The Cistern Keepers' records may reveal where the Winter Levy went, but releasing them could implicate both senatorial patrons and harbor brokers. Each faction wants the ledgers, and none trusts the others to publish the whole account.",
      "faction_ids": [
        "fac_house_lamps",
        "fac_open_hand",
        "fac_cistern_keepers"
      ]
    }
  ]
}

response.output:
{
  "world_id": "wld_serein_glass",
  "name": "The Shard Expanse",
  "description": "A lone traveller crosses a desert of glass, where the ground keeps the day's heat and the wind carries old sounds from beneath it. There are no broad roads, only narrow paths marked by cairns and the occasional dark seam in the glittering plain. Water is scarce; silence is scarcer. A traveller can cross the expanse, but every route passes through places where someone has chosen what may be remembered.",
  "locations": [
    {
      "id": "loc_ashen_gate",
      "name": "Ashen Gate",
      "description": "A low arch of blackened stone at the desert's edge. Its inner face bears thousands of shallow cuts, each said to mark a traveller who left and did not return."
    },
    {
      "id": "loc_whisper_plain",
      "name": "Whisper Plain",
      "description": "A wide field of pale glass. At dusk, footsteps from long ago seem to cross it, though no tracks remain by morning."
    },
    {
      "id": "loc_stillwell",
      "name": "Stillwell",
      "description": "A deep shaft capped with a brass lid. Water rises only when the lid is kept shut through the hottest hours, making its small settlement careful about every visitor."
    },
    {
      "id": "loc_buried_bell",
      "name": "The Buried Bell",
      "description": "A great bronze bell lies half-submerged in fused sand. It rings once in the coldest part of each night, and the sound points toward a different horizon each time."
    },
    {
      "id": "loc_last_shelter",
      "name": "Last Shelter",
      "description": "A windbreak of stone and sailcloth at the far side of the crossing. Its keeper offers a place to sleep in exchange for one true account of the road."
    }
  ],
  "factions": [
    {
      "id": "fac_lidkeepers",
      "name": "The Lidkeepers",
      "description": "The careful stewards of Stillwell. They ration water by household and keep the brass lid shut even when the thirsty crowd begs them to draw more.",
      "location_ids": ["loc_stillwell"]
    },
    {
      "id": "fac_quiet_measure",
      "name": "The Quiet Measure",
      "description": "A sparse company of route-markers who maintain the cairns. They erase any mark that claims a path is safe, insisting the desert changes when certainty takes root.",
      "location_ids": ["loc_ashen_gate", "loc_whisper_plain"]
    },
    {
      "id": "fac_bellwardens",
      "name": "The Bellwardens",
      "description": "Keepers of the night watch at the Buried Bell. They record its direction but conceal the oldest records, fearing that its final bearing will draw a crowd no water could sustain.",
      "location_ids": ["loc_buried_bell"]
    }
  ],
  "rules": [
    {
      "id": "rul_glass_heat",
      "statement": "The glass stores the day's heat and releases it after sunset, so the safest crossing hours are before dawn.",
      "category": "physics"
    },
    {
      "id": "rul_sound_memory",
      "statement": "Sounds spoken over unbroken glass may return at dusk, but never with the same distance or direction twice.",
      "category": "metaphysics"
    },
    {
      "id": "rul_shut_well",
      "statement": "Stillwell yields water only if its lid remains closed through the hottest part of the day.",
      "category": "physics"
    },
    {
      "id": "rul_unclaimed_path",
      "statement": "No cairn marks a safe route; those who maintain the paths must leave their certainty unspoken.",
      "category": "social"
    }
  ],
  "history": [
    {
      "id": "evt_first_fall",
      "name": "The Great Fusing",
      "description": "A season of fierce heat melted the dunes into a hard, shining plain. The first survivors found the old wells sealed beneath it.",
      "era": "Before the crossing roads",
      "location_ids": ["loc_whisper_plain", "loc_stillwell"]
    },
    {
      "id": "evt_bell_burial",
      "name": "The Bell Went Under",
      "description": "A settlement rang its bronze bell to summon help during a dry year. The sound brought no water, and the bell vanished beneath a surge of molten sand.",
      "era": "The dry years",
      "location_ids": ["loc_buried_bell"]
    },
    {
      "id": "evt_markers_departure",
      "name": "The Markers' Vow",
      "description": "After a marked route led a caravan into a heat basin, its survivors abandoned fixed maps and began tending cairns without promising safety.",
      "era": "The first crossings",
      "location_ids": ["loc_ashen_gate", "loc_whisper_plain"]
    },
    {
      "id": "evt_shelter_oath",
      "name": "An Account for Rest",
      "description": "The keeper of Last Shelter began asking each arrival for a true account of the road, preserving details that the shifting cairns could not.",
      "era": "The present era",
      "location_ids": ["loc_last_shelter"]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_water_and_records",
      "name": "The Well's Measure",
      "description": "The Lidkeepers refuse to open Stillwell more often, while the Quiet Measure argues that the Bellwardens' hidden records may reveal another source of water. A traveller carrying fresh observations could tip the balance—or expose the well to a rush it cannot survive.",
      "faction_ids": ["fac_lidkeepers", "fac_quiet_measure", "fac_bellwardens"]
    },
    {
      "id": "cnf_final_bearing",
      "name": "The Last Direction",
      "description": "The Bellwardens fear the bell's next bearing will summon desperate seekers; the Quiet Measure wants the bearing shared so no one crosses blind. Both sides may need a lone traveller to carry the record beyond the desert.",
      "faction_ids": ["fac_quiet_measure", "fac_bellwardens"]
    }
  ]
}

