response.output:
{
  "world_id": "wld_veyra",
  "name": "The Threefold Reach",
  "description": "The Threefold Reach is a tense fantasy world of three rival city-states bound by a narrow valley and an uneasy alliance. They face the Ashen Choir, an enemy whose silent processions leave abandoned towns and memories that no survivor can agree upon. Each city holds a different piece of the valley's defense, but distrust over old betrayals threatens to undo their pact. Here, promises have a physical consequence: a vow spoken before the valley's standing stones is heard by the land itself, and a broken oath causes one stone to crack.",
  "locations": [
    {
      "id": "loc_amber_quay",
      "name": "Amber Quay",
      "description": "A harbor city built on terraces of honey-colored stone, wealthy from river trade and guarded by a chain that can seal the estuary. Its council fears that an alliance will turn its fleet into another city's weapon."
    },
    {
      "id": "loc_vowstone",
      "name": "The Vowstone Mere",
      "description": "A wind-scoured basin at the valley's center, where three ancient standing stones rise from a shallow lake. Envoys meet on a narrow causeway; every oath sworn here is believed to bind the land as well as the speaker."
    },
    {
      "id": "loc_cinderhold",
      "name": "Cinderhold",
      "description": "A fortress-city carved into the black slopes of a dormant volcano. Its glasswrights and foundry clans command the valley's strongest defenses, though their furnaces are failing and their leaders conceal how little fuel remains."
    }
  ],
  "factions": [
    {
      "id": "fac_amber_council",
      "name": "Council of Amber Quay",
      "description": "Merchant houses and ship captains who support the alliance only if they retain control of the estuary chain and the right to withdraw their fleet.",
      "location_ids": ["loc_amber_quay"]
    },
    {
      "id": "fac_merewardens",
      "name": "Merewardens",
      "description": "Keepers of the causeway and interpreters of the standing stones. They claim no city may command the stones, but some quietly alter the record of vows to prevent panic.",
      "location_ids": ["loc_vowstone"]
    },
    {
      "id": "fac_cinder_clans",
      "name": "Cinder Clans",
      "description": "Foundry families who guard Cinderhold's walls and craft weapons from volcanic glass. They demand the other cities share the cost of keeping the furnaces alive.",
      "location_ids": ["loc_cinderhold"]
    },
    {
      "id": "fac_ashen_choir",
      "name": "Ashen Choir",
      "description": "A disciplined host that advances without banners or audible commands. Its ranks include people from vanished settlements, though none seem to remember joining.",
      "location_ids": []
    }
  ],
  "rules": [
    {
      "id": "rul_stone_vows",
      "statement": "A vow spoken before the three standing stones is witnessed by the valley; when its speaker knowingly breaks it, one stone cracks and the sound carries to all three cities.",
      "category": "metaphysics"
    },
    {
      "id": "rul_memory_ash",
      "statement": "Ash left by the Ashen Choir cannot erase a memory outright, but it makes the memory's details disagree among those who share it.",
      "category": "metaphysics"
    },
    {
      "id": "rul_no_silent_orders",
      "statement": "Within the valley, a command must be spoken aloud to be obeyed; written orders can guide a reader, but cannot compel action.",
      "category": "social"
    }
  ],
  "history": [
    {
      "id": "evt_chain_betrayal",
      "name": "The Night of the Lowered Chain",
      "description": "Amber Quay lowered its estuary chain during a siege, trapping Cinderhold's relief ships outside the harbor. The cities have argued ever since over whether the order came from the council or a forged dispatch.",
      "era": "Thirty years before the alliance",
      "location_ids": ["loc_amber_quay"]
    },
    {
      "id": "evt_first_crack",
      "name": "The First Stone Cracks",
      "description": "At a failed peace meeting, a Cinderhold envoy broke a public pledge to share fuel. A standing stone split with a sound heard across the valley, and the Merewardens began recording every treaty spoken at the basin.",
      "era": "Twelve years before the alliance",
      "location_ids": ["loc_vowstone", "loc_cinderhold"]
    },
    {
      "id": "evt_vanishing_towns",
      "name": "The Empty Road",
