      "location_ids": ["loc_cinderhold", "loc_vowstone"]
    },
    {
      "id": "evt_threefold_pact",
      "name": "The Threefold Pact",
      "description": "With the Choir nearing the valley, envoys from all three cities swore to share warnings, shelter displaced people, and defend the causeway. The pact's wording leaves control of the final military command unresolved.",
      "era": "Present",
      "location_ids": ["loc_amber_quay", "loc_vowstone", "loc_cinderhold"]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_shared_command",
      "name": "Who Gives the Last Order?",
      "description": "The pact binds the cities to defend one another but names no commander. Each city fears that yielding authority will let a rival sacrifice its people or seize the valley after the Choir is defeated.",
      "faction_ids": ["fac_amber_council", "fac_merewardens", "fac_cinder_clans"]
