response.output:
{
  "world_id": "wld_five_boroughs",
  "name": "The Grid Below",
  "description": "Five Boroughs is a sprawling megacity built around a buried transit lattice that once made its districts feel like one place. The lattice's central exchange lies beneath Meridian, where a terrorist attack has severed routes, stranded neighborhoods, and turned routine commutes into dangerous negotiations. The city is all wet concrete, ration lights, patched machinery, and exhausted people trying to keep one another alive. In the attack's aftermath, borough leaders publicly promise unity while competing for access to the few working tunnels. A peculiar feature of the grid complicates every rescue: its oldest switches respond to the combined pressure of passengers on opposing platforms, making a route open only when people on both sides choose to risk the crossing together.",
  "locations": [
    {
      "id": "loc_meridian",
      "name": "Meridian Borough",
      "description": "The civic core, built above the central transit exchange. Blast-scarred concourses sit beneath government towers, and emergency gates divide officials from the crowds they claim to represent."
    },
    {
      "id": "loc_ironward",
      "name": "Ironward Borough",
      "description": "A dense belt of repair yards and worker housing where residents keep obsolete trains running with scavenged parts. Its workshops can restore a route, but their power supply is failing."
    },
    {
      "id": "loc_silt",
      "name": "Silt Borough",
      "description": "Low-lying blocks where seepage from the city's foundations floods basements and service tunnels. Neighbors use rooftop footbridges to move food and news when the tracks go dark."
    },
    {
      "id": "loc_crown",
      "name": "Crown Borough",
      "description": "A crowded vertical district of stacked homes and markets. Its elevated platforms survived the first blast, making it a refuge and a bottleneck for people displaced from below."
    },
    {
      "id": "loc_ashline",
      "name": "Ashline Borough",
      "description": "The outer borough, where freight spurs meet the city's waste fields. Its residents control the only surface road capable of carrying heavy equipment toward Meridian."
    }
  ],
  "factions": [
    {
      "id": "fac_mutuals",
      "name": "Platform Mutuals",
      "description": "Volunteer crews from all five boroughs who organize food, first aid, and dangerous tunnel crossings. They insist that any working route must remain open to ordinary passengers.",
      "location_ids": [
        "loc_meridian",
        "loc_ironward",
        "loc_silt",
        "loc_crown",
        "loc_ashline"
      ]
    },
    {
      "id": "fac_civic",
      "name": "Civic Continuity Office",
      "description": "A besieged municipal authority that controls the central exchange's security gates. It says restricted access is necessary to prevent another attack, but will not publish its passenger lists or route priorities.",
      "location_ids": [
        "loc_meridian",
        "loc_crown"
      ]
    },
    {
      "id": "fac_switchwrights",
      "name": "Switchwright Union",
      "description": "Rail technicians who know the lattice's hand-operated controls and preserve its unwritten maintenance lore. They will not energize a line without crews stationed at both ends.",
      "location_ids": [
        "loc_ironward",
        "loc_meridian"
      ]
    },
    {
      "id": "fac_signal",
      "name": "Quiet Signal",
      "description": "A clandestine network that moves messages through maintenance relays and claims to have intercepted warnings before the attack. Its members disagree over whether exposing the source would prevent another strike or ignite reprisals.",
      "location_ids": [
        "loc_silt",
        "loc_ashline",
        "loc_meridian"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_lattice_pressure",
      "statement": "The oldest transit switches open only when pressure plates at opposing platforms are loaded at the same time; one-sided activation leaves the route locked.",
      "category": "technology"
    },
    {
      "id": "rul_grid_power",
      "statement": "The buried grid cannot carry power and passenger traffic on the same damaged branch without risking a fire, so every reopened line requires a deliberate tradeoff.",
      "category": "technology"
    },
    {
      "id": "rul_borough_compact",
      "statement": "No borough may commandeer another borough's food stores or rail crews without a public vote of its local assembly.",
      "category": "social"
    }
  ],
  "history": [
    {
      "id": "evt_founding",
      "name": "The Borough Compact",
      "description": "After years of district feuds, the boroughs formed a compact that gave local assemblies control over supplies while placing the transit lattice under shared stewardship.",
      "era": "Founding era",
      "location_ids": [
        "loc_meridian",
        "loc_ironward",
        "loc_silt",
        "loc_crown",
        "loc_ashline"
      ]
    },
    {
      "id": "evt_switch_custom",
      "name": "The Two-Platform Oath",
      "description": "A deadly early power test taught rail crews that the old pressure switches required people at both ends. The union turned the discovery into a safety oath: no line would be opened by a crew acting alone.",
      "era": "First generation of the grid",
      "location_ids": [
        "loc_ironward",
        "loc_meridian"
      ]
    },
    {
      "id": "evt_blackout",
      "name": "The Long Blackout",
      "description": "A cascading failure cut the outer routes for eleven days. Residents improvised roof bridges and hand-carried supplies, creating networks that still outlast official communications.",
      "era": "Two decades before the attack",
      "location_ids": [
        "loc_silt",
        "loc_crown",
        "loc_ashline"
      ]
    },
    {
      "id": "evt_attack",
      "name": "The Meridian Strike",
      "description": "An explosive attack shattered the central exchange and disabled the most direct links between boroughs. No group has claimed responsibility, and conflicting relay records leave open whether the warnings were ignored, forged, or deliberately delayed.",
      "era": "Present day",
      "location_ids": [
        "loc_meridian"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_access",
      "name": "Who Gets the First Train",
      "description": "The Civic Continuity Office wants to reserve the repaired line for security and essential personnel, while the Platform Mutuals demand that displaced residents ride first. The Switchwright Union can make the route work, but its crews refuse to choose sides without a public agreement.",
      "faction_ids": [
        "fac_civic",
        "fac_mutuals",
        "fac_switchwrights"
      ]
    },
    {
      "id": "cnf_warning",
      "name": "The Missing Warning",
      "description": "Quiet Signal may know who sent the intercepted warning before the Meridian strike. The Civic Continuity Office wants the records sealed; the Platform Mutuals want them shared. Revealing the source could expose a preventable failure—or put the signal network's informants in immediate danger.",
      "faction_ids": [
        "fac_signal",
        "fac_civic",
        "fac_mutuals"
      ]
    }
  ]
}

