{
  "world_id": "wld_ironveil",
  "name": "The Iron Veil",
  "description": "The kingdom of Veyr prospers behind a chain of immense stone wards, where every public office, school, and workshop is bound by law to reject claims of hidden power. Its people credit the wards to patient engineering: iron ribs, tuned stone chambers, and crews who keep the joints sealed against the bitter salt wind beyond the frontier. Now the oldest chambers have begun to fall out of tune. The Crown calls it sabotage; the ward-keepers call it neglect. Beyond the walls, pale dust gathers in the fields, and no one can agree whether the kingdom is being warned, abandoned, or slowly buried. This is a grim land of practical ingenuity, inherited fear, and a prosperity built on maintenance nobody wants to pay for.",
  "locations": [
    {
      "id": "loc_veyre",
      "name": "Veyre, the Crown City",
      "description": "A soot-dark capital arranged around a dry canal and the oldest ward chamber. Its civic bells mark work shifts as well as curfew, and every household owes the Crown a yearly allotment of iron."
    },
    {
      "id": "loc_nine_gates",
      "name": "The Nine Gates",
      "description": "A line of fortified passes where the ward's stone ribs cross the mountain road. The western gates hum unevenly in cold weather, and crews sleep beside the mechanisms for fear a night of silence will go unnoticed."
    },
    {
      "id": "loc_saltmere",
      "name": "Saltmere Flats",
      "description": "A former grain plain now crusted white with windblown mineral dust. Abandoned mile markers emerge after storms, each bearing a notch that records how far the ward's boundary once reached."
    }
  ],
  "factions": [
    {
      "id": "fac_crown",
      "name": "The Crown Ledger",
      "description": "The royal ministries that tax iron, license engineers, and enforce the ban on forbidden practices. Officials conceal ward failures to prevent panic and preserve the trade that keeps Veyre fed.",
      "location_ids": ["loc_veyre", "loc_nine_gates"]
    },
    {
      "id": "fac_keepers",
      "name": "The Stone Keepers",
      "description": "A hereditary corps of masons and bell-tuners responsible for the ward chambers. They keep private repair records and suspect that old construction plans were deliberately altered.",
      "location_ids": ["loc_nine_gates", "loc_veyre"]
    },
    {
      "id": "fac_saltfolk",
      "name": "The Saltmere Kin",
      "description": "Displaced farmers and scavengers who salvage the flats and trade in fragments of pre-kingdom records. They want the Crown to admit the ward has retreated and let their families return to the lost fields.",
      "location_ids": ["loc_saltmere", "loc_veyre"]
    }
  ],
  "rules": [
    {
      "id": "rul_no_hidden_force",
      "statement": "No hidden force has ever been shown to alter the natural order; every claimed wonder must withstand ordinary inspection.",
      "category": "metaphysics"
    },
    {
      "id": "rul_ward_maintenance",
      "statement": "The ward holds only while its stone joints remain sealed and its iron ribs stay tuned to the chamber bells.",
      "category": "physics"
    },
    {
      "id": "rul_public_oath",
      "statement": "Teaching or practicing forbidden rites is a crime, and suspicion alone can cost a household its ration rights.",
      "category": "social"
    },
    {
      "id": "rul_iron_tithe",
      "statement": "Every district owes a fixed iron tithe to the Crown before local tools or repairs may be supplied.",
      "category": "technology"
    },
    {
      "id": "rul_tolling_bells",
      "statement": "A silent ward bell requires an immediate gate closure, even when that closure strands travelers outside.",
      "category": "social"
    }
  ],
  "history": [
    {
      "id": "evt_first_wall",
      "name": "The Raising of the First Ward",
      "description": "The early Crown joined scattered mountain barriers into one maintained line. Its builders left no account of why the design followed the strange notches on older mile markers.",
      "era": "Founding Years",
      "location_ids": ["loc_nine_gates", "loc_veyre"]
    },
    {
      "id": "evt_salt_retreat",
      "name": "The White Retreat",
      "description": "A succession of failed harvests drove families from Saltmere. The Crown declared the loss a natural event and barred settlement beyond the gates.",
      "era": "Three Generations Ago",
      "location_ids": ["loc_saltmere", "loc_nine_gates"]
    },
    {
      "id": "evt_records_sealed",
      "name": "The Sealed Measures",
      "description": "The Crown confiscated early ward plans after a dispute over the iron tithe. The Stone Keepers retained incomplete copies, whose measurements disagree with the official maps.",
      "era": "The Year of Closed Archives",
      "location_ids": ["loc_veyre", "loc_nine_gates"]
    },
    {
      "id": "evt_bell_failures",
      "name": "The Uneven Toll",
      "description": "Several western bells began to falter, while pale dust appeared on the far side of the gates. The Crown blamed theft; the Keepers found no missing iron.",
      "era": "Present Winter",
      "location_ids": ["loc_nine_gates", "loc_saltmere"]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_hidden_repairs",
      "name": "The Cost of Silence",
      "description": "The Crown Ledger withholds reports of failing chambers to protect public order, while the Stone Keepers demand iron and permission to open sealed sections before the line gives way.",
      "faction_ids": ["fac_crown", "fac_keepers"]
    },
    {
      "id": "cnf_returning_fields",
      "name": "The Fields Beyond the Gate",
      "description": "The Saltmere Kin press to cross the boundary and reclaim their old farms. The Crown calls any crossing a threat to the ward, while the Keepers fear that closing the gates again will hide evidence of the retreat.",
      "faction_ids": ["fac_crown", "fac_saltfolk", "fac_keepers"]
    }
  ]
}

