response.output:
{
  "world_id": "wld_vesper_tide",
  "name": "Vesper Tide",
  "description": "Vesper is a remote, tidally locked moon where a narrow belt of habitable caverns lies between a sun-blasted ridge and a frozen dark side. Miners of the Lumen Cooperative uncovered dreamstone beneath the oldest ice shelf: a crystal that carries dreams from sleeper to sleeper across the colony. The visions arrive with the intimacy of memory and the unsettling certainty of witnessed events, though no two people agree on who first dreamed them. As shared dreams begin to reveal things the colony has never recorded, the question is no longer whether the crystal is communicating, but whether its message belongs to the living.",
  "locations": [
    {
      "id": "loc_suture",
      "name": "Suture Mine",
      "description": "A descending chain of pressurized shafts cut through blue-black ice and mineral seams. The first dreamstone was found in a chamber whose walls hum faintly when miners sleep nearby."
    },
    {
      "id": "loc_lantern",
      "name": "Lantern Hab",
      "description": "The colony's crowded central habitat, lit by amber grow-lamps and stitched together from mining modules. Most residents first experience the shared dreams here, where thin walls make private sleep almost impossible."
    },
    {
      "id": "loc_echo_vault",
      "name": "Echo Vault",
      "description": "A sealed laboratory built around the largest crystal specimen. Its instruments record brain rhythms, but the data sometimes contains a second pulse that no sleeper's monitor detects."
    },
    {
      "id": "loc_meltline",
      "name": "Meltline Orchard",
      "description": "A greenhouse warmed by geothermal pipes at the edge of the habitable belt. Its vines grow in patterns that resemble maps from the colony's recurring dreams, though no one planted them that way."
    },
    {
      "id": "loc_night_gate",
      "name": "Night Gate",
      "description": "A pressure lock opening onto the moon's frozen hemisphere. Beyond it, a field of dark ice reflects the stars even in daylight, and returning crews sometimes describe the same stranger waiting outside."
    }
  ],
  "factions": [
    {
      "id": "fac_lumen",
      "name": "Lumen Cooperative",
      "description": "The miners and habitat stewards who keep Vesper supplied. They want the dreamstone secured as a communal resource, but disagree over whether anyone has the right to regulate what people dream.",
