response.output:
{
  "world_id": "wld_paper_crown",
  "name": "The Pending Floor",
  "description": "A sarcastic institutional thriller set inside a sealed civic tower where every floor is governed by a different committee and every emergency requires three copies. The tower's only crossing to the outside is the skybridge, a glass corridor whose doors open only when two rival departments certify that the other department is responsible. Tonight, the building's master ledger has begun recording disasters several minutes before they happen. Officials call this a clerical irregularity. The staff trapped inside call it Tuesday, until the ledger predicts a death and names the person who will approve the paperwork.",
  "locations": [
    {
      "id": "loc_skybridge",
      "name": "The Skybridge",
      "description": "A glass-enclosed passage between the tower and its annex, suspended above a river of traffic. Its access panel demands matching signatures from both ends, a design praised as foolproof by the committee that lost the key."
    }
  ],
  "factions": [
    {
      "id": "fac_records",
      "name": "Office of Permanent Records",
      "description": "Archivists who guard the master ledger and insist that anything written in it becomes official, whether or not it has happened yet.",
      "location_ids": [
        "loc_skybridge"
      ]
    },
    {
      "id": "fac_continuity",
      "name": "Continuity Committee",
      "description": "Emergency planners who control the tower's exits and describe every locked door as a temporary improvement to public safety.",
      "location_ids": [
        "loc_skybridge"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_ledger",
      "statement": "An entry in the master ledger becomes unavoidable only after two rival offices independently certify it.",
      "category": "metaphysics"
    },
    {
      "id": "rul_copies",
      "statement": "A certified document has force only when its original and two carbon copies remain together.",
      "category": "social"
    },
    {
      "id": "rul_silence",
      "statement": "The tower's public address system records spoken objections as formal consent unless a witness files a correction before the next announcement.",
      "category": "technology"
    }
  ],
  "history": [
    {
      "id": "evt_charter",
      "name": "The Unanimous Charter",
      "description": "The departments created the master ledger to prevent blame from vanishing between offices. Its founding ceremony ended with every official certifying that someone else had written the charter.",
      "era": "Founding year",
      "location_ids": [
        "loc_skybridge"
      ]
    },
    {
      "id": "evt_first_prediction",
      "name": "The Appointment That Arrived Early",
      "description": "The ledger listed a maintenance failure before the inspection began. Both offices certified the entry, and the failure occurred moments later. The official report called the timing a successful administrative forecast.",
      "era": "Three years ago",
      "location_ids": [
        "loc_skybridge"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_unsigned_exit",
      "name": "The Exit Requires Approval",
      "description": "The Records Office wants the ledger entry predicting a fatality sealed; the Continuity Committee wants it certified so the building can be evacuated under procedure. Each needs the other's signature, and neither trusts what the ledger may make official.",
      "faction_ids": [
        "fac_records",
        "fac_continuity"
      ]
    }
  ]
}

