  "name": "The Crownlands of Vesperreach",
  "description": "Vesperreach is a realm of storm-cut coasts, pine-dark valleys, and a vast northern ice shelf that groans like a living thing. Three royal houses each claim the vacant throne, their rival oaths dividing the old kingdom just as warmth rises from beneath the ice. In this epic fantasy, every crown carries a debt: generations ago, the first monarch sealed an ancient enemy below the frozen wastes, and the seal is failing. The enemy does not merely hunger for conquest; it remembers the names of those who bound it, and speaks them in the dreams of their heirs.",
  "locations": [
    {
      "id": "loc_ashenmere",
      "name": "Ashenmere",
      "description": "The old capital, built on a black-stone island where three rivers meet. Its empty throne room is kept open to the winter wind, and each claimant holds court in a different wing."
    },
    {
      "id": "loc_icevein",
      "name": "The Icevein Shelf",
      "description": "A sprawling northern field of blue ice, split by fissures that glow faintly at night. The oldest cracks emit warm air and whispers in a language no living scholar can place."
    },
    {
      "id": "loc_bellweather",
      "name": "Bellweather Pass",
      "description": "A high mountain road lined with bronze bells. When an army crosses, the bells toll in the key of its commander’s childhood lullaby, a phenomenon locals treat as an omen."
    },
    {
      "id": "loc_thornwake",
      "name": "Thornwake Wood",
      "description": "A tangled forest of silver-barked trees whose roots follow buried roads. Travelers who stray from the paths sometimes emerge days later with memories belonging to the dead."
    },
    {
      "id": "loc_saltcairn",
      "name": "Saltcairn Harbor",
      "description": "A western port where tide caves conceal the first monarch’s weather-worn boundary stones. The harbor’s salt merchants profit from the conflict, while their divers report a new light beneath the seabed."
    }
  ],
  "factions": [
    {
      "id": "fac_house_varyn",
      "name": "House Varyn",
      "description": "Keepers of Ashenmere and the royal archives, the Varyns claim the throne by descent from the last crowned sovereign. Their careful ledgers hide a missing page from the treaty that sealed the northern enemy.",
      "location_ids": [
        "loc_ashenmere"
      ]
    },
    {
      "id": "fac_house_eld",
      "name": "House Eld",
      "description": "A mountain dynasty that commands Bellweather Pass and the realm’s strongest mounted guard. The Elds argue that the crown belongs to whoever can keep the roads open, and their current heir hears a voice in the bells.",
      "location_ids": [
        "loc_bellweather"
      ]
    },
    {
      "id": "fac_house_morren",
      "name": "House Morren",
      "description": "A coastal house whose ships and salt stores make it indispensable to every claimant. The Morrens seek the throne through an old marriage pact and quietly search the tide caves for proof of their claim.",
      "location_ids": [
        "loc_saltcairn"
      ]
    },
    {
      "id": "fac_the_unwoken",
      "name": "The Unwoken",
      "description": "An ancient presence bound beneath the Icevein Shelf. It reaches the surface through dreams, offering each royal heir a different version of the truth about the first monarch’s bargain.",
      "location_ids": [
        "loc_icevein",
        "loc_thornwake"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_oath_echo",
      "statement": "An oath spoken before a witness-tree takes root in the speaker’s shadow; breaking it causes the tree to shed a leaf bearing the oathbreaker’s true name.",
      "category": "metaphysics"
    },
    {
      "id": "rul_ice_memory",
      "statement": "The oldest ice preserves spoken words, but releases them only when warmed by living blood.",
      "category": "metaphysics"
    },
    {
      "id": "rul_bell_tone",
      "statement": "The bronze bells of Bellweather sound a person’s childhood lullaby whenever that person leads an armed host through the pass.",
      "category": "metaphysics"
    },
    {
      "id": "rul_crown_witness",
      "statement": "No ruler is recognized in Vesperreach until three independent houses witness the coronation and surrender a token of their own lineage.",
      "category": "social"
    },
    {
      "id": "rul_craft_limits",
      "statement": "Craft is worked by hand, water, wind, and fire; no known device can cast a force beyond the reach of a trained bow.",
      "category": "technology"
    }
  ],
  "history": [
    {
      "id": "evt_first_bargain",
      "name": "The First Monarch’s Bargain",
      "description": "The first monarch joined three rival houses to bind the Unwoken beneath the northern ice. The pact demanded a royal memory from each house, and the lost memories were hidden in separate places so no ruler could undo the seal alone.",
      "era": "Founding Age",
      "location_ids": [
        "loc_icevein",
        "loc_ashenmere",
        "loc_thornwake"
      ]
    },
    {
      "id": "evt_broken_line",
      "name": "The Empty Throne",
      "description": "When the last sovereign died without naming an heir, the three houses produced competing genealogies. Their dispute halted the coronation and fractured the royal guard.",
      "era": "The Present Interregnum",
      "location_ids": [
        "loc_ashenmere"
      ]
    },
    {
      "id": "evt_pass_lullaby",
      "name": "The Pass That Sang",
      "description": "A generation ago, the bells rang for a commander who had not yet been born. The prophecy was dismissed until that child, now heir to House Eld, led troops through the pass.",
      "era": "The Bell Years",
      "location_ids": [
        "loc_bellweather"
      ]
    },
    {
      "id": "evt_warm_fissure",
      "name": "The Red Thaw",
      "description": "A recent tremor opened a warm fissure in the shelf. Since then, trees in Thornwake have grown leaves in midwinter, and people across the realm wake speaking the same unfamiliar name.",
      "era": "The Present Interregnum",
      "location_ids": [
        "loc_icevein",
        "loc_thornwake"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_three_claims",
      "name": "The Three Claims",
      "description": "House Varyn, House Eld, and House Morren each have a plausible route to the throne. Their bids for allies and control of the capital threaten to turn a disputed succession into open war.",
      "faction_ids": [
        "fac_house_varyn",
        "fac_house_eld",
        "fac_house_morren"
      ]
    },
    {
      "id": "cnf_failing_seal",
      "name": "The Failing Seal",
      "description": "The Unwoken offers each heir a different path to victory in exchange for memories bound into the ancient pact. Accepting could end the civil war quickly, but may also restore the enemy’s strength.",
      "faction_ids": [
        "fac_house_varyn",
        "fac_house_eld",
        "fac_house_morren",
        "fac_the_unwoken"
      ]
    },
    {
      "id": "cnf_hidden_memory",
      "name": "The Missing Memory",
      "description": "The royal archives, the mountain bells, and the tide caves each hold part of the truth about the first monarch’s bargain. No claimant can learn the whole truth without trusting a rival, while the Unwoken works to keep them divided.",
      "faction_ids": [
        "fac_house_varyn",
        "fac_house_eld",
        "fac_house_morren",
        "fac_the_unwoken"
      ]
    }
  ]
}

