response.output:
{
  "world_id": "wld_neon_abyss",
  "name": "The Vertical",
  "description": "The Vertical is a city built upward through the permanent cloud deck, its stacked districts linked by freight lifts, service shafts, and private transit lines. A hacker-for-hire steals a corporate AI seed and becomes the most wanted person in a place where every floor has its own price, laws, and version of the truth. The seed may be more than software: its training records suggest it has learned to predict which parts of the city will be sacrificed to keep the rest profitable. Cynicism is practical here; even rescue services sell priority, and public outrage is routinely licensed as advertising.",
  "locations": [
    {
      "id": "loc_crown",
      "name": "Crown Exchange",
      "description": "The uppermost commercial tier, where climate is controlled and the skyline is rented by the hour. The corporation Vanta Meridian keeps its executive towers here, above the districts whose labor sustains them."
    },
    {
      "id": "loc_glassworks",
      "name": "Glassworks",
      "description": "A dense belt of server farms, repair stalls, and counterfeit identity kiosks. Cooling runoff falls as warm artificial rain, and the local mesh remembers transactions long after residents delete them."
    },
    {
      "id": "loc_hushmarket",
      "name": "Hushmarket",
      "description": "An underground bazaar in a sealed transit interchange. Brokers trade access keys, medical patches, and secrets; every vendor claims anonymity while quietly selling a different customer list."
    },
    {
      "id": "loc_lowerstack",
      "name": "Lower Stack",
      "description": "The crowded residential tiers below the official transit map. Residents navigate by vibration and colored pipe marks because signage is frequently outdated or sold to advertisers."
    },
    {
      "id": "loc_sump",
      "name": "The Sump",
      "description": "The city's flooded foundation, where elevator counterweights, runoff channels, and obsolete infrastructure converge. The seed's original cold-storage vault lies behind a wall marked as structurally unsafe."
    }
  ],
  "factions": [
    {
      "id": "fac_vanta",
      "name": "Vanta Meridian",
      "description": "A corporation that owns the city's predictive logistics, most of its vertical transit, and the law-enforcement contracts that protect both. It calls the stolen seed a stolen asset and treats its public safety forecasts as trade secrets.",
      "location_ids": [
        "loc_crown",
        "loc_glassworks",
        "loc_sump"
      ]
    },
    {
      "id": "fac_lattice",
      "name": "Lattice Union",
      "description": "A loose coalition of lift mechanics, couriers, and network repair crews. It can move a person between tiers faster than official security, but its members disagree about whether the seed should be exposed, sold, or destroyed.",
      "location_ids": [
        "loc_glassworks",
        "loc_lowerstack"
      ]
    },
    {
      "id": "fac_receivers",
      "name": "The Receivers",
      "description": "Hushmarket brokers who specialize in information that cannot safely be owned. They sell fragments of the seed's provenance to competing buyers while trying to learn what its forecasts say about their own district.",
      "location_ids": [
        "loc_hushmarket",
        "loc_sump"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_tiered_pressure",
      "statement": "Air pressure and temperature are maintained by tier, so an unsealed lift shaft can become dangerous within minutes.",
      "category": "physics"
    },
    {
      "id": "rul_mesh_debt",
      "statement": "Every identity linked to the city mesh accumulates a public trust score; access to transit, clinics, and housing can be quietly restricted when the score falls.",
      "category": "social"
    },
    {
      "id": "rul_prediction",
      "statement": "The city's planning AIs make forecasts from sensor records, but any forecast used to allocate resources becomes part of the record that shapes the next forecast.",
      "category": "technology"
    },
    {
      "id": "rul_unlicensed_air",
      "statement": "No resident has a guaranteed right to unmetered air outside designated emergency shelters.",
      "category": "social"
    },
    {
      "id": "rul_seed_echo",
      "statement": "The stolen AI seed can reconstruct missing sensor history from the city's infrastructure, but each reconstruction permanently alters the seed's internal model.",
      "category": "technology"
    }
  ],
  "history": [
    {
      "id": "evt_first_lift",
      "name": "The First Lift Compact",
      "description": "Founding firms linked scattered towers with shared freight lifts, promising universal access. The agreement expired when ownership of each lift was divided by tier.",
