response.output:
{
  "world_id": "wld_bellweather_weekend",
  "name": "The Bellweather Weekend",
  "description": "At Brackenmere Manor, a weekend party brings a polished guest list together under one roof—and leaves every guest with a reason to hide something. When a murder turns the gathering into a closed-circle mystery, rain-swollen lanes and a washed-out bridge keep help at a distance. The mood is intimate rather than grim: tea trays, sharp manners, old loyalties, and small village kindnesses sit beside carefully guarded secrets. The manor’s unusual barometer ledger, whose ink records each abrupt pressure change, may help reconstruct the stormy night, but it cannot say who acted or why.",
  "locations": [
    {
      "id": "loc_brackenmere_manor",
      "name": "Brackenmere Manor",
      "description": "A remote country manor of pale stone, snug parlors, and a glass-roofed conservatory overlooking a rain-dark lake. Its guests and household staff share close quarters during the party. In the entrance hall, a barometer is paired with a century-old ledger: the housekeeper records its readings, and the ink blots whenever the pressure drops sharply."
    },
    {
      "id": "loc_wickford_crossing",
      "name": "Wickford Crossing",
      "description": "A tiny lane-side hamlet at the manor’s only dependable approach, with a post room, a tea counter, and a narrow bridge over the Mere. After heavy rain, the bridge can become unsafe, leaving locals to pass news and supplies by footpath while visitors wait at the house."
    }
  ],
  "factions": [
    {
      "id": "fac_brackenmere_household",
      "name": "The Brackenmere Household",
      "description": "The family, guests, and long-serving staff who maintain the manor’s traditions. They present a united welcome, but old debts and private bargains divide them over what should be kept within the house.",
      "location_ids": [
        "loc_brackenmere_manor"
      ]
    },
    {
      "id": "fac_wickford_neighbors",
      "name": "The Wickford Neighbors",
      "description": "A close-knit circle of residents who keep the hamlet running and know which visitors arrive, leave, or change their story. They value discretion, though they will not let a vulnerable neighbor be made a scapegoat.",
      "location_ids": [
        "loc_wickford_crossing"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_mere_weather",
      "statement": "When the Mere floods, the bridge is unsafe for carts and ordinary foot traffic until the water falls.",
      "category": "physics"
    },
    {
      "id": "rul_ledger_limits",
      "statement": "The barometer ledger records pressure changes, not identities, intentions, or exact events.",
      "category": "other"
    },
    {
      "id": "rul_household_discretion",
      "statement": "At Brackenmere, staff are expected to protect guests’ privacy, but no household custom grants anyone authority to conceal a death from the proper authorities.",
      "category": "social"
    },
    {
      "id": "rul_neighbor_reciprocity",
      "statement": "In Wickford, people share practical help in bad weather, and a favor freely given is not treated as proof of guilt.",
      "category": "social"
    }
  ],
  "history": [
    {
      "id": "evt_bridge_flood",
      "name": "The Bridge Flood",
      "description": "A severe storm once swept away the old crossing and stranded the manor household for two days. The rebuilt bridge made the hamlet and manor more connected, but the lane still becomes impassable in hard rain.",
      "era": "Three generations ago",
      "location_ids": [
        "loc_wickford_crossing"
      ]
    },
    {
      "id": "evt_ledger_started",
      "name": "The First Barometer Notes",
      "description": "After the flood, a former housekeeper began recording the barometer whenever the weather shifted. Successive staff kept the habit, turning the ledger into a quiet record of storms and household routines.",
      "era": "After the Bridge Flood",
      "location_ids": [
        "loc_brackenmere_manor"
      ]
    },
    {
      "id": "evt_weekend_invitation",
      "name": "The Weekend Invitation",
      "description": "The current host invited a deliberately mixed company to Brackenmere: family, old friends, and people whose business with one another was never fully settled. A murder during the gathering makes their competing versions of the evening impossible to ignore.",
      "era": "The present",
      "location_ids": [
        "loc_brackenmere_manor"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_private_truths",
      "name": "Privacy Against Protection",
      "description": "The Brackenmere Household wants to contain scandal and preserve its traditions; the Wickford Neighbors want an honest account before an outsider or a convenient suspect is blamed. Both sides have information that could help, and reasons to reveal it only on their own terms.",
      "faction_ids": [
        "fac_brackenmere_household",
        "fac_wickford_neighbors"
      ]
    }
  ]
}

