response.output:
{
  "world_id": "wld_hollow_carrier",
  "name": "The Hollow Carrier",
  "description": "At the end of a logging road, a lone cabin shelters a radio host whose midnight broadcasts reach almost no one. Then a voice begins answering on a frequency she never uses: her own, older by a handful of hours, warning her of choices she has not yet made. Each warning sounds more urgent—and less like a warning. The surrounding forest swallows ordinary signals, leaving the cabin as the only point where the future can speak. Here, every attempt to change what is coming seems to give the voice a clearer path back.",
  "locations": [
    {
      "id": "loc_blackfir_cabin",
      "name": "Blackfir Cabin",
      "description": "A one-room broadcast station built from dark logs above a shuttered logging spur. The transmitter occupies a bolted steel cabinet; its tuning dial sometimes turns by itself during the long hush after the host signs off. Beyond the walls, the forest muffles sound so completely that even a nearby branch can seem impossibly far away."
    }
  ],
  "factions": [
    {
      "id": "fac_night_desk",
      "name": "The Night Desk",
      "description": "A loose circle of overnight listeners who record unusual transmissions and trade tapes by post. They believe the strange voice is an elaborate hoax, but their copied recordings contain replies none of them remembers hearing.",
      "location_ids": [
        "loc_blackfir_cabin"
      ]
    },
    {
      "id": "fac_second_voice",
      "name": "The Second Voice",
      "description": "The host's future selves, heard only through the receiver. They agree that the broadcast must continue, but disagree about what must be sacrificed to keep it from reaching someone else.",
      "location_ids": [
        "loc_blackfir_cabin"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_hush_frequency",
      "statement": "The future voice can enter the receiver only during the first forty seconds of silence after the host signs off.",
      "category": "metaphysics"
    },
    {
      "id": "rul_memory_toll",
      "statement": "Each time the host records a message from her future, one ordinary word disappears from her memory until she hears that word spoken aloud by another person.",
      "category": "metaphysics"
    },
    {
      "id": "rul_copied_tape",
      "statement": "A copied recording preserves the voice but not the warning's original wording; each copy replaces one detail with something the listener fears.",
      "category": "technology"
    },
    {
      "id": "rul_forest_static",
      "statement": "No signal sent from beyond the logging road reaches the cabin clearly, and no signal sent from the cabin can be reliably located from outside.",
      "category": "physics"
    }
  ],
  "history": [
    {
      "id": "evt_last_logging_shift",
      "name": "The Last Shift",
      "description": "When the logging spur closed, its workers left a portable transmitter in the cabin. The station kept it running as a community call-in show, though no one could explain why the receiver remained warm after power was cut.",
      "era": "Years before the broadcast",
      "location_ids": [
        "loc_blackfir_cabin"
      ]
    },
    {
      "id": "evt_first_reply",
      "name": "The First Reply",
      "description": "During a routine sign-off, the host heard her own voice give the exact time of a power failure that occurred minutes later. She filed the tape away and told no one.",
      "era": "The first week of transmissions",
      "location_ids": [
        "loc_blackfir_cabin"
      ]
    },
    {
      "id": "evt_tape_exchange",
      "name": "The Tape Exchange",
      "description": "Listeners in the Night Desk began mailing copies of the recording to compare what they heard. Each copy carried a different final sentence, though the host's voice remained unmistakable.",
      "era": "After the first reply",
      "location_ids": [
        "loc_blackfir_cabin"
      ]
    },
    {
      "id": "evt_missing_word",
      "name": "The Missing Word",
      "description": "The host forgot the name of the road she had driven for years. The future voice supplied it on air, then asked her not to repeat the name into the microphone.",
      "era": "The present broadcast",
      "location_ids": [
        "loc_blackfir_cabin"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_warning_or_invitation",
      "name": "Warning or Invitation",
      "description": "The Night Desk wants the tapes preserved and circulated as proof; the Second Voice insists that every copy makes the signal easier to follow. The host must decide whether to broadcast a final warning that may also be the invitation the voice has been waiting for.",
      "faction_ids": [
        "fac_night_desk",
        "fac_second_voice"
      ]
    }
  ]
}

