response.output:
{
  "world_id": "wld_sundered_tides",
  "name": "The Sundered Reach",
  "description": "A storm-lashed archipelago where every safe passage depends on who has sworn to keep it. The islands’ rival powers trade favors, secrets, and grudges across narrow channels, while old pirate codes still shape the law of the sea. A reformed raider must recover a stolen map before its shifting routes expose a hidden harbor—and the people who trusted them to keep it secret.",
  "locations": [
    {
      "id": "loc_needlewake",
      "name": "Needlewake Island",
      "description": "A steep volcanic island ringed by reefs that make its harbor nearly impossible to approach without a local pilot. Its cliffs are studded with signal mirrors used to guide ships through the channels."
    },
    {
      "id": "loc_brasswater",
      "name": "Brasswater Quay",
      "description": "A crowded port built on stilts above a tidal lagoon. Captains settle disputes here in public, where breaking a sworn bargain costs more than losing a ship."
    },
    {
      "id": "loc_bellshoal",
      "name": "Bell Shoal",
      "description": "A low island whose buried bronze bells ring beneath the sand when the tide turns. Their pattern marks a safe route that changes with each season."
    },
    {
      "id": "loc_saltglass",
      "name": "Saltglass Isle",
      "description": "A pale island of wind-polished cliffs and salt pans. Its glassmakers craft lenses that reveal faint ink on maps when moonlight passes through them."
    },
    {
      "id": "loc_crowsnest",
      "name": "Crow's Nest Cay",
      "description": "A small, wooded island used as a neutral meeting ground. Its central tree bears carved tokens left by crews seeking pardon or passage."
    },
    {
      "id": "loc_drowned_steps",
      "name": "The Drowned Steps",
      "description": "A staircase of ancient stone descending beneath the sea from a nameless rock. At the lowest tide, it leads to a sealed vault whose entrance is hidden by living coral."
    }
  ],
  "factions": [
    {
      "id": "fac_tidewardens",
      "name": "The Tidewardens",
      "description": "Pilot families who maintain the archipelago's signal routes and claim the right to close any channel they judge unsafe. Their knowledge is inherited, but their loyalties are not always shared.",
      "location_ids": [
        "loc_needlewake",
        "loc_bellshoal"
      ]
    },
    {
      "id": "fac_quay_compact",
      "name": "The Quay Compact",
      "description": "Merchants and harbor judges who keep Brasswater open through carefully witnessed agreements. They want the stolen map contained before it upends the balance of port access.",
      "location_ids": [
        "loc_brasswater",
        "loc_saltglass"
      ]
    },
    {
      "id": "fac_ashen旗",
      "name": "The Ashen Pennant",
      "description": "A loose fleet of former raiders who now escort ships for pay. They respect their old captain's change of life, but some believe the stolen map could buy them lasting independence.",
      "location_ids": [
        "loc_crowsnest",
        "loc_needlewake"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_tide_routes",
      "statement": "The safe channels shift with the season; a chart without current bell patterns can lead a ship onto reef.",
      "category": "physics"
    },
    {
      "id": "rul_sworn_bargains",
      "statement": "A harbor bargain witnessed by three captains is binding in every port that honors the Quay Compact.",
      "category": "social"
    },
    {
      "id": "rul_moon_ink",
      "statement": "Saltglass lenses reveal concealed map ink only under moonlight, and each exposure fades the hidden lines a little.",
      "category": "technology"
    }
  ],
  "history": [
    {
      "id": "evt_bell_compacts",
      "name": "The Bell Compact",
      "description": "After a season of wrecks, pilot families marked the shifting channels with buried bells and agreed to share their patterns with the ports.",
      "era": "Three generations ago",
      "location_ids": [
        "loc_bellshoal",
        "loc_brasswater"
      ]
    },
    {
      "id": "evt_cinder_pardon",
      "name": "The Cinder Pardon",
      "description": "A raiding fleet surrendered its colors at Crow's Nest Cay and accepted escort work in exchange for a public pardon. The former captain became a rare bridge between port law and pirate custom.",
      "era": "Seven years ago",
      "location_ids": [
        "loc_crowsnest",
        "loc_needlewake"
      ]
    },
    {
      "id": "evt_map_taken",
      "name": "The Chart Vanishes",
      "description": "A map showing a route through the Drowned Steps disappeared from a guarded archive. The theft was blamed on the reformed captain, though the evidence was arranged too neatly to settle the matter.",
      "era": "The present season",
      "location_ids": [
        "loc_brasswater",
        "loc_drowned_steps"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_chart_claims",
      "name": "Who Owns the Route",
      "description": "The Tidewardens want the map destroyed to protect their authority over safe passage, while the Quay Compact wants it secured as common property. The Ashen Pennant sees it as leverage for a future beyond paid escort work.",
      "faction_ids": [
        "fac_tidewardens",
        "fac_quay_compact",
        "fac_ashen旗"
      ]
    },
    {
      "id": "cnf_pardon_debt",
      "name": "The Price of Pardon",
      "description": "The former captain's pardon depends on proving the theft was not an attempt to revive their old life. Each faction offers help at a price, and refusing every bargain may leave the captain with no allies.",
      "faction_ids": [
        "fac_quay_compact",
        "fac_ashen旗"
      ]
    }
  ]
}

