      "id": "loc_needlewake",
      "name": "Needlewake Island",
      "description": "A steep volcanic island ringed by reefs that make its harbor nearly impossible to approach without a local pilot. Its cliffs are studded with signal mirrors used to guide ships through the channels."
    },
    {
      "id": "loc_brasswater",
      "name": "Brasswater Quay",
      "description": "A crowded port built on stilts above a tidal lagoon. Captains settle disputes here in public, where breaking a sworn bargain costs more than losing a ship."
    },
    {
      "id": "loc_bellshoal",
      "name": "Bell Shoal",
      "description": "A low island whose buried bronze bells ring beneath the sand when the tide turns. Their pattern marks a safe route that changes with each season."
    },
