{
  "world_id": "wld_saffron_wind",
  "name": "The Saffron Reach",
  "description": "Across the Saffron Reach, a caravan road stitches together green oases beneath a vast, sunlit sky. Merchants carry silk, brasswork, stories, and letters between cities whose fortunes depend on shared wells. The mood is generous but never carefree: tea is poured for strangers, debts are remembered for generations, and war can close a road faster than a sandstorm. Now rival oasis cities contest the ancient channels that feed their gardens, drawing a traveling merchant caravan into a struggle where every load of water has a history and every honest bargain might keep the peace.",
  "locations": [
    {
      "id": "loc_saffron_gate",
      "name": "Saffron Gate",
      "description": "A walled market town at the western edge of the desert, where caravan masters hire guides and traders swap news over saffron tea. Its shaded courtyards welcome travelers, though city clerks carefully record every water skin brought through the gates."
    },
    {
      "id": "loc_mirror_well",
      "name": "Mirror Well",
      "description": "A deep spring in a ring of white stone, said to reflect the face of whoever last drew water rather than the person leaning over it. Caravans rest beneath tamarisk trees here, and rival envoys have long met on neutral ground."
    },
    {
      "id": "loc_qamar",
      "name": "Qamar",
      "description": "A garden city of date palms and blue-tiled roofs, thriving where an underground channel rises into open pools. Its people prize careful stewardship, and its public water ledger is read aloud each new moon."
    },
    {
      "id": "loc_namar",
      "name": "Namar",
      "description": "A neighboring oasis city built around a broad basin and a lively riverfront bazaar. Namar's dyers and silk merchants insist that Qamar has diverted more than its share of the old channel."
    },
    {
      "id": "loc_singing_cut",
      "name": "The Singing Cut",
      "description": "A narrow passage through copper-colored hills, where wind passing over old stone sluices makes a low, flute-like note. The channel beneath the cut links both cities, and a hidden gate there could decide which gardens live through the dry season."
    },
    {
      "id": "loc_juniper_camp",
      "name": "Juniper Camp",
      "description": "A seasonal stopping place around a grove of juniper and a cluster of caravanserai courtyards. Its cooks serve lentils to anyone who arrives before sunset, while its roofed well offers the last dependable water before the eastern dunes."
    }
  ],
  "factions": [
    {
      "id": "fac_qamar_council",
      "name": "Council of Qamar",
      "description": "Qamar's merchants, gardeners, and channel keepers govern by public tally. They claim their city repaired the old waterworks and therefore deserves first draw, but some councilors fear the ledger hides an earlier injustice.",
      "location_ids": [
        "loc_qamar",
        "loc_singing_cut"
      ]
    },
    {
      "id": "fac_namar_compact",
      "name": "Namar's Basin Compact",
      "description": "A coalition of dyers, boatmen, and orchard families united to restore Namar's customary share of the channel. Its leaders favor negotiation, though the city's thirsty neighborhoods are demanding action before the next harvest fails.",
      "location_ids": [
        "loc_namar",
        "loc_singing_cut"
      ]
    },
    {
      "id": "fac_open_cup",
      "name": "The Open Cup",
      "description": "A loose fellowship of caravan guides, innkeepers, and well tenders who keep neutral rest stops supplied. They preserve old travel songs that contain practical directions, and they will not let either city turn a shared well into a military post.",
      "location_ids": [
        "loc_saffron_gate",
        "loc_mirror_well",
        "loc_juniper_camp"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_shared_well",
      "statement": "At an unclaimed well, the first draw belongs to the oldest traveler present, and no host may refuse a guest a cup without losing standing at every caravanserai on the road.",
      "category": "social"
    },
    {
      "id": "rul_channel_tone",
      "statement": "The old stone channels sing when water passes through them; a change in pitch reveals a blocked sluice or a diverted flow before the water level visibly falls.",
      "category": "physics"
    },
    {
      "id": "rul_ledger_oath",
      "statement": "A water debt witnessed by three households is binding until repaid in water, labor, or an agreed equivalent; spoken promises alone do not alter the public tally.",
      "category": "social"
    }
  ],
  "history": [
    {
      "id": "evt_first_channel",
      "name": "The First Channel",
      "description": "Builders from Qamar and Namar cut a shared aqueduct through the hills after a punishing drought. Their agreement divided water by season and required both cities to maintain the Singing Cut.",
      "era": "Founding years",
      "location_ids": [
        "loc_qamar",
        "loc_namar",
        "loc_singing_cut"
      ]
    },
    {
      "id": "evt_mirror_treaty",
      "name": "The Mirror Well Treaty",
      "description": "After a caravan was caught between the cities' armed patrols, their elders met at Mirror Well and promised that travelers and neutral wells would remain outside any quarrel.",
      "era": "Three generations ago",
      "location_ids": [
        "loc_mirror_well"
      ]
    },
    {
      "id": "evt_silent_sluice",
      "name": "The Silent Sluice",
      "description": "A channel gate failed during a dry summer, and Namar's lower gardens withered while Qamar's pools stayed full. Neither city admitted fault; the public ledgers thereafter recorded every repair and every bucket drawn.",
      "era": "The dry summer",
      "location_ids": [
        "loc_qamar",
        "loc_namar",
        "loc_singing_cut"
      ]
    },
    {
      "id": "evt_caravan_arrival",
      "name": "The Arrival of the Saffron Caravan",
      "description": "A merchant caravan reached Saffron Gate carrying silk for both cities and a weathered survey map hidden among its trade papers. The map appears to show an older branch of the channel, giving the travelers evidence that could settle the dispute or reignite it.",
      "era": "Present season",
      "location_ids": [
        "loc_saffron_gate",
        "loc_singing_cut"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_water_share",
      "name": "The Divided Channel",
      "description": "Qamar and Namar are preparing for a fight over the flow through the Singing Cut. The caravan's old survey map may prove that the accepted division was altered long ago, but revealing it could implicate respected families in both cities.",
      "faction_ids": [
        "fac_qamar_council",
        "fac_namar_compact"
      ]
    },
    {
      "id": "cnf_neutral_road",
      "name": "The Neutral Road",
      "description": "The Open Cup wants the caravan road and its wells kept safe, while both cities are tempted to seize supplies and close crossings to pressure their rival. The caravan must decide whether to protect neutrality, choose a side, or risk exposing the evidence before the next draw.",
      "faction_ids": [
        "fac_qamar_council",
        "fac_namar_compact",
        "fac_open_cup"
      ]
    }
  ]
}

